def check_balanced_groups(groups: List[str]) -> bool:
    """Given a list of groups (which are separated by some spaces in the input string), check if all groups are balanced (each open brace is properly closed) and not nested within each other
    >>> check_balanced_groups(['()', '(())', '(()())'])
    True
    >>> check_balanced_groups(['()', '(((()()))', '(()())'])
    False
    """
    groups_with_nesting: List[str] = []
    groups: List[str] = groups
    while groups:
        group: str = groups.pop(0)
        if group not in groups_with_nesting:
            groups_with_nesting.append(group)
    return not any((group not in groups) for group in groups_with_nesting)


