def is_prime(number: int) -> bool:
    """ Check if given positive integer is a prime number.
    >>> is_prime(5)
    True
    >>> is_prime(11)
    True
    >>> is_prime(12)
    False
    """
    if number < 2:
        return False
    elif number == 2:
        return True
    else:
        for i in range(2, int(number ** 0.5) + 1):
            if number % i == 0:
                return False
        return True

