    """ Checks if the given input string is balanced
    Balanced means the number of open brackets is equal to the number of closed brackets and all open brackets
    are closed.
    Example:
    >>> is_balanced('()()()()')
    True
    >>> is_balanced('()()()(((')
    False
    """
    count = 0
    for char in string_to_check:
        if char == '(':
            count += 1
        else:
            count -= 1

        if count < 0:
