def max_depth(paren_string: str) -> int:
    """ Input to this function is a string represented a group of nested parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    This function counts the total depth of nested parentheses.
    For example, (()()) has depth 2 while ((())) has depth 3.
    """
    max_depth: int = 0
    curr_depth: int = 0
    for character in paren_string:
        if character == "(":
            curr_depth += 1
            max_depth = max(max_depth, curr_depth)
        else:
            curr_depth -= 1
    return max_depth


